package frigolite

import (
	"fmt"
	"strings"
	"testing"
)

// TestTriggerWhitespaceRobustFire verifies that a CREATE TRIGGER declaration
// with arbitrary whitespace between the timing/event/ON keywords still fires.
// SQLite accepts e.g. "BEFORE INSERT             ON tbl" (SQL generated by
// string concatenation in the TCL test harness), and trigger matching must not
// rely on exact single-space substrings.
func TestTriggerWhitespaceRobustFire(t *testing.T) {
	db, err := Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	execOK := func(sql string) {
		t.Helper()
		if r := db.Exec(sql); r.Error != nil {
			t.Fatalf("exec %q: %v", sql, r.Error)
		}
	}

	execOK("DROP TABLE IF EXISTS tbl")
	execOK("DROP TABLE IF EXISTS log")
	execOK("CREATE TABLE tbl(a PRIMARY KEY, b, c) WITHOUT rowid")
	execOK("CREATE TABLE log(a, b, c)")
	execOK("INSERT INTO tbl VALUES(1, 2, 3); INSERT INTO log VALUES(1, 2, 3); INSERT INTO log VALUES(10, 20, 30);")
	// Many spaces between INSERT and ON (as produced by the transpiled
	// harness: "BEFORE " + stmtRange(0,6) + "             ON tbl ...").
	execOK("CREATE TRIGGER the_trigger BEFORE INSERT             ON tbl BEGIN DELETE FROM log WHERE a = 1; END")
	r := db.Query("INSERT INTO tbl VALUES(5, 6, 7); SELECT * FROM log ORDER BY a;")
	if r.Error != nil {
		t.Fatalf("query: %v", r.Error)
	}
	var got []string
	for _, row := range r.Rows {
		for _, v := range row {
			got = append(got, fmt.Sprintf("%v", v))
		}
	}
	// The BEFORE INSERT trigger must delete log row (1,2,3); (10,20,30) remains.
	want := "10 20 30"
	flat := strings.Join(got, " ")
	if flat != want {
		t.Fatalf("got %q want %q", flat, want)
	}
}
